type T = Record<Lang, string>;
export type TourType = 'bike' | 'mtb' | 'moto' | 'hike' | 'winterhike' | 'xc' | 'toboggan' | 'snowshoe';
export type Level = 'easy' | 'medium' | 'hard';
export const HOME: [number, number] = [47.27268, 12.42573];
export interface Tour {
  id: string; type: TourType; name: T; start: T; lat: number; lon: number; startKm: number; startMin: number;
  km?: number | null; up?: number | null; time?: T | null; level?: Level | null; season?: T | null;
  highlights: Record<Lang, string[]>; family?: boolean | null; url: string; gpx?: string | null; img?: string | null; floodlit?: boolean | null;
}
export interface Place {
  id: string; name: string; tagline: T; intro: T; lat: number; lon: number; km: number; min: number; url: string; img: Record<Season, string | null>;
  dontMiss: { name: T; url: string }[]; know: Record<Lang, string[]>;
}

